import os
import base64
import six

from robot.utils.robottime import timestr_to_secs

from .base import BaseInterface
from ..util import wrap_result
from ..validators import IsOneOf, IsString
from ..converter import to_int, to_bool


class OtherProceduresInterface(BaseInterface):
    """the interface for other keywords"""

    def set_dac_word(self,
                     dac_word,
                     target_fsm=None,
                     timeout=60,
                     alias="default"):
        """Set DAC word.

        :param integer dac_word: DAC word.
        :param string target_fsm: primary or secondary. /
        None means a default Admin API behavior.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        dac_word = to_int(dac_word)
        timeout = timestr_to_secs(timeout)
        IsOneOf(None, "primary", "secondary").check(target_fsm)

        parameters = {
            "dacWord": dac_word,
        }

        if target_fsm:
            parameters["targetFSM"] = target_fsm

        self.store.get(alias).execute_procedure("setDacWord",
                                                parameters, timeout)

    def set_vendor_file(self, vendor_file, technology_type=None,
                        timeout=300, alias="default"):
        """Set vendor file.

        :param string vendor_file: xml file or path to xml file.
        :param string technology_type: either "fdd", "tdd" or None for new implementation of Admin
        :param float timeout: Time to wait for positive procedure result
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(vendor_file)

        if os.path.isfile(vendor_file):
            with open(vendor_file, 'r') as f:
                vendor_file = f.read()

        six_vendor_file = six.b(vendor_file)
        b64_vendor_file = base64.b64encode(six_vendor_file)
        parameters = {"inputFileContent": b64_vendor_file.decode("utf-8")}

        if technology_type is not None:
            IsString().check(technology_type)
            parameters["technologyType"] = technology_type

        return self.store.get(alias).execute_procedure("setVendorFile", parameters, timeout)

    def download_vendor_file(self, target_file_name, timeout=60, alias="default"):
        """download vendor file.

        :param string target_file_name: target vendor_file filename.
        :param float timeout: Time to wait for positive procedure result
        :param string alias: Name of execution context.
        """

        IsString().check(target_file_name)
        self.store.get(alias).execute_infomodel_request(
            "downloadVendorFile", {}, timeout, output_file_name=target_file_name)

    def get_dac_word(self, timeout=60, alias="default"):
        """Get DAC word.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: integer
        :return: DAC word
        """
        timeout = timestr_to_secs(timeout)

        dac_word = self.store.get(alias).execute_infomodel_request(
            "getDacWord", {}, timeout)
        return int(dac_word)

