    def get_fhs_list(self, detailed_output=False, timeout=90, alias='default'):
        """ Get FHS list
        https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-getFhsList.html

        :param bool detailed_output: return full request response when True
        :param float timeout: Time to wait for positive procedure result
        :param string alias: Name of execution context.
        :return: FHS list dictionary or full request response
        """

        timeout = timestr_to_secs(timeout)
        detailed_output = to_bool(detailed_output)
        response = self.store.get(alias).execute_customer_procedure("getFhsList", {}, timeout)
        if detailed_output:
            return response
        else:
            return response.get("requestMessage", []).get("fhs", [])

